    validate_graph(graph)
    in_degree = defaultdict(int)
    for task, deps in graph.items():
        for dep in deps:
            in_degree[dep] += 1

    ready = deque([task for task in graph if in_degree[task] == 0])
    order = []

    while ready:
        task = ready.popleft()
        order.append(task)
        for dep in graph[task]:
            in_degree[dep] -= 1
